+        values
+    }
+
+    fn complete_path(
+        value_os: &clap_lex::RawOsStr,
+        current_dir: Option<&std::path::Path>,
+        is_wanted: impl Fn(&std::path::Path) -> bool,
+    ) -> Vec<OsString> {
